// The demo lowers markers.largeDatasetThreshold to this so batching is
// reachable at a few hundred points. The shipped default is 0, meaning off:
// see note 02 below for why.
var LAB_THRESHOLD = 200

// Seeded PRNG (mulberry32) so every configuration below plots the SAME scene.
// A benchmark over two different random datasets measures nothing.
function labRng(seed) {
  return function () {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    var t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// A wandering series with enough vertical travel that markers pile up on the
// turns, which is where the batching trade-off is visible.
// gapMode: 'none' | 'sparse' (every 7th null) | 'half' (every other null).
function labData(points, gapMode) {
  var rng = labRng(0x51a3c7)
  var t0 = Date.UTC(2024, 0, 1)
  var out = new Array(points)
  var y = 60
  for (var i = 0; i < points; i++) {
    y += (rng() - 0.5) * 9
    y = Math.max(8, Math.min(112, y))
    var nulled =
      (gapMode === 'sparse' && i % 7 === 0) ||
      (gapMode === 'half' && i % 2 === 0)
    out[i] = [t0 + i * 3600000, nulled ? null : +y.toFixed(2)]
  }
  return out
}

// Every SVG mark is a live DOM node, so counting inside the chart is the
// clearest view of what a render actually built.
function labCensus(sel) {
  var el = document.querySelector(sel || '#chart')
  if (!el) return { paths: 0, markers: 0, nodes: 0 }
  return {
    // series geometry only: the axes and grid draw paths too, and those are
    // a fixed cost that would blur the comparison
    paths: el.querySelectorAll(
      '.apexcharts-line, .apexcharts-area, .apexcharts-marker-batch',
    ).length,
    markers: el.querySelectorAll(
      '.apexcharts-series-markers-wrap .apexcharts-marker',
    ).length,
    nodes: el.getElementsByTagName('*').length,
  }
}

// Stateless DOM helpers, shared by the vanilla, React and Vue builds.
function labSelected(segId) {
  var seg = document.getElementById(segId)
  return (
    seg.querySelector('button[aria-pressed="true"]') ||
    seg.querySelector('button')
  )
}

function labSetPressed(segId, btn) {
  var seg = document.getElementById(segId)
  Array.prototype.forEach.call(seg.querySelectorAll('button'), function (b) {
    b.setAttribute('aria-pressed', b === btn ? 'true' : 'false')
  })
}

// Read the four segmented controls into one config object.
function labConfig() {
  return {
    points: parseInt(labSelected('labPoints').getAttribute('data-v'), 10),
    gaps: labSelected('labGaps').getAttribute('data-v'),
    markers: labSelected('labMarkers').getAttribute('data-v') === 'on',
    batch: labSelected('labBatch').getAttribute('data-v') === 'on',
  }
}

// Apply a config to a copy of the sample's own chart options, so the lab and
// the code shown in the sample never drift apart.
function labApply(base, cfg) {
  var o = Object.assign({}, base)
  o.chart = Object.assign({}, base.chart)
  o.markers = Object.assign({}, base.markers, {
    size: cfg.markers ? 4 : 0,
    largeDatasetThreshold: cfg.batch ? LAB_THRESHOLD : 0,
  })
  o.series = [{ name: 'Sensor', data: labData(cfg.points, cfg.gaps) }]
  return o
}

// One variable at a time against a common baseline, so each row answers one
// question. Rows 2 and 3 are the null story, rows 4 and 5 the marker story.
var LAB_MATRIX = [
  {
    key: 'clean',
    label: 'baseline: no gaps, no markers',
    color: '#94a3b8',
    gaps: 'none',
    markers: false,
    batch: false,
  },
  {
    key: 'nulls',
    label: 'half the values null',
    color: '#b45309',
    gaps: 'half',
    markers: false,
    batch: false,
  },
  {
    key: 'nullsBatched',
    label: 'half null, batched',
    color: '#047857',
    gaps: 'half',
    markers: false,
    batch: true,
  },
  {
    key: 'markers',
    label: 'markers on',
    color: '#b45309',
    gaps: 'none',
    markers: true,
    batch: false,
  },
  {
    key: 'markersBatched',
    label: 'markers on, batched',
    color: '#047857',
    gaps: 'none',
    markers: true,
    batch: true,
  },
]

function labShowMatrix(rows, points) {
  document.getElementById('labMatrixEmpty').hidden = true
  var host = document.getElementById('labMatrixData')
  host.hidden = false

  var maxMs = 1
  rows.forEach(function (r) {
    if (r.ms > maxMs) maxMs = r.ms
  })

  host.innerHTML = rows
    .map(function (r) {
      var pct = Math.max(2, Math.round((r.ms / maxMs) * 100))
      return (
        '<div class="lab-lane">' +
        '<span class="lab-who"><span class="dot" style="background:' +
        r.color +
        '"></span>' +
        r.label +
        '</span>' +
        '<div class="lab-meter"><span style="width:' +
        pct +
        '%;background:' +
        r.color +
        '"></span></div>' +
        '<span class="lab-num">' +
        r.ms +
        ' ms <em>&middot; ' +
        (r.paths + r.markers).toLocaleString() +
        ' els</em></span>' +
        '</div>'
      )
    })
    .join('')

  var byKey = {}
  rows.forEach(function (r) {
    byKey[r.key] = r
  })
  var ratio = function (a, b) {
    return (a.ms / Math.max(b.ms, 0.1)).toFixed(1)
  }
  var parts = []
  if (byKey.clean && byKey.nulls && byKey.nullsBatched) {
    parts.push(
      'Nulling half the values costs <b>' +
        ratio(byKey.nulls, byKey.clean) +
        '&times;</b> the baseline, and almost none of that is the line: the ' +
        'series is <b>' +
        byKey.nulls.paths +
        ' path element' +
        (byKey.nulls.paths === 1 ? '' : 's') +
        '</b> either way, because the breaks are subpaths of one ' +
        '<code>d</code>. It is the <b>' +
        byKey.nulls.markers.toLocaleString() +
        ' dots</b> every isolated point gets, on a chart with markers off. ' +
        'Batching those brings it to <b>' +
        byKey.nullsBatched.ms +
        ' ms</b>.',
    )
  }
  if (byKey.markers && byKey.markersBatched) {
    parts.push(
      'Markers on their own add <b>' +
        byKey.markers.markers.toLocaleString() +
        ' elements</b> and <b>' +
        Math.max(0, byKey.markers.ms - byKey.clean.ms).toFixed(1) +
        ' ms</b>, which batching returns as <b>' +
        ratio(byKey.markers, byKey.markersBatched) +
        '&times; faster</b> at ' +
        points.toLocaleString() +
        ' points on this device.',
    )
  }
  document.getElementById('labVerdict').innerHTML = parts.join(' ')
}

var options = {
  series: [{ name: 'Sensor', data: labData(2000, 'none') }],
  chart: {
    height: 340,
    type: 'line',
    animations: { enabled: false },
    fontFamily: 'Helvetica, Arial, sans-serif',
    toolbar: { show: false },
    zoom: { enabled: false },
  },
  colors: ['#2563eb'],
  stroke: { curve: 'straight', width: 2 },
  dataLabels: { enabled: false },
  markers: { size: 0, strokeWidth: 2, strokeColors: '#fff' },
  grid: { borderColor: '#e7ecf5' },
  xaxis: {
    type: 'datetime',
    tooltip: { enabled: false },
    labels: { style: { colors: '#8b97ae' } },
  },
  yaxis: {
    labels: {
      style: { colors: '#8b97ae' },
      formatter: function (val) {
        return val.toFixed(0)
      },
    },
  },
  tooltip: { x: { format: 'dd MMM HH:mm' } },
}

var chart = new ApexCharts(document.querySelector('#chart'), options)
chart.render()

// The template builds `chart` from the chart block above and renders it. This
// script wires the lab: the segmented controls, a Render button that rebuilds
// at the chosen configuration, and a matrix pass that renders the same scene
// four ways and compares. labInit lives here rather than in the shared head
// script because it needs to own the template's `chart` binding.
var labBusy = document.getElementById('labBusy')

function labUpdateMetrics(ms) {
  var c = labCensus('#chart')
  document.getElementById('mTime').innerHTML =
    (ms > 0 ? ms : '-') + '<small>ms</small>'
  document.getElementById('mPaths').textContent = c.paths.toLocaleString()
  document.getElementById('mMarkers').textContent = c.markers.toLocaleString()
  document.getElementById('mNodes').textContent = c.nodes.toLocaleString()
}

// Rebuild #chart with the given config and report what it cost. Timed around
// destroy + construct + render, which is the whole cost a page actually pays.
function labRenderWith(cfg) {
  var opts = labApply(options, cfg)
  var t = performance.now()
  chart.destroy()
  chart = new ApexCharts(document.querySelector('#chart'), opts)
  return chart.render().then(function () {
    var ms = +(performance.now() - t).toFixed(1)
    var c = labCensus('#chart')
    return { ms: ms, paths: c.paths, markers: c.markers }
  })
}

function labRender() {
  labBusy.classList.add('on')
  return labRenderWith(labConfig()).then(function (r) {
    labBusy.classList.remove('on')
    labUpdateMetrics(r.ms)
  })
}

function labRunMatrix() {
  var points = labConfig().points
  var btnM = document.getElementById('labMatrix')
  var btnR = document.getElementById('labRender')
  btnM.disabled = true
  btnR.disabled = true
  labBusy.classList.add('on')

  // Warm once at this point count first: an unwarmed comparison of these
  // configurations once made the slower one look faster, because the first
  // render paid for the JIT.
  var rows = []
  var run = labRenderWith({
    points: points,
    gaps: 'none',
    markers: false,
    batch: false,
  })
  LAB_MATRIX.forEach(function (m) {
    run = run
      .then(function () {
        return labRenderWith({
          points: points,
          gaps: m.gaps,
          markers: m.markers,
          batch: m.batch,
        })
      })
      .then(function (r) {
        rows.push({
          key: m.key,
          label: m.label,
          color: m.color,
          ms: r.ms,
          paths: r.paths,
          markers: r.markers,
        })
      })
  })

  return run
    .then(function () {
      // leave the stage on the user's own selection, not the last matrix run
      return labRenderWith(labConfig())
    })
    .then(function (r) {
      labShowMatrix(rows, points)
      labUpdateMetrics(r.ms)
      labBusy.classList.remove('on')
      btnM.disabled = false
      btnR.disabled = false
    })
}

// The side-by-side pair: 400 points at marker size 5 in a narrow chart, so the
// markers overlap several deep and the merge is visible rather than argued.
function labBuildMiniPair() {
  var data = labData(400, 'none')
  var mini = function (threshold) {
    return {
      chart: {
        type: 'line',
        height: 170,
        animations: { enabled: false },
        toolbar: { show: false },
        zoom: { enabled: false },
        parentHeightOffset: 0,
        fontFamily: 'Helvetica, Arial, sans-serif',
      },
      series: [{ name: 'Sensor', data: data }],
      colors: ['#2563eb'],
      stroke: { curve: 'straight', width: 2 },
      dataLabels: { enabled: false },
      markers: {
        size: 5,
        strokeWidth: 2,
        strokeColors: '#fff',
        largeDatasetThreshold: threshold,
      },
      grid: { show: false, padding: { left: 2, right: 2, top: 0, bottom: 0 } },
      xaxis: {
        type: 'datetime',
        labels: { show: false },
        axisBorder: { show: false },
        axisTicks: { show: false },
        tooltip: { enabled: false },
      },
      yaxis: { show: false },
      tooltip: { enabled: false },
      legend: { show: false },
    }
  }

  var pairs = [
    { sel: '#labMiniPer', out: 'labMiniPerCount', threshold: 0 },
    { sel: '#labMiniBat', out: 'labMiniBatCount', threshold: LAB_THRESHOLD },
  ]
  pairs.forEach(function (p) {
    var c = new ApexCharts(document.querySelector(p.sel), mini(p.threshold))
    c.render().then(function () {
      var census = labCensus(p.sel)
      document.getElementById(p.out).textContent =
        census.markers > 0
          ? census.markers.toLocaleString() + ' marker elements'
          : '1 path, ' + data.length.toLocaleString() + ' subpaths'
    })
  })
}

;['labPoints', 'labGaps', 'labMarkers', 'labBatch'].forEach(function (segId) {
  document.getElementById(segId).addEventListener('click', function (e) {
    var btn = e.target.closest('button')
    if (btn) labSetPressed(segId, btn)
  })
})

document.getElementById('labRender').addEventListener('click', labRender)
document.getElementById('labMatrix').addEventListener('click', labRunMatrix)

// Seed the readout off the template's own first render, then build the pair.
requestAnimationFrame(function poll() {
  if (typeof chart !== 'undefined' && chart.w && chart.w.globals) {
    labUpdateMetrics(0)
    labBuildMiniPair()
  } else {
    requestAnimationFrame(poll)
  }
})

.lab {
  max-width: 760px;
  margin: 12px auto;
  font-family: Helvetica, Arial, sans-serif;
  color: #101a2b;
}
.lab-lede {
  font-size: 13.5px;
  line-height: 1.6;
  color: #47536b;
  margin: 4px 6px 14px;
}
.lab-lede code,
.lab-note code,
.lab-caption code,
.lab-verdict code {
  background: #eef2fa;
  padding: 1px 5px;
  border-radius: 3px;
  font-size: 12px;
}
.lab-console {
  background: #fff;
  border: 1px solid #dce3f0;
  border-radius: 12px;
  overflow: hidden;
}
/* controls */
.lab-controls {
  display: flex;
  gap: 18px;
  align-items: flex-end;
  flex-wrap: wrap;
  padding: 14px 16px;
  border-bottom: 1px solid #dce3f0;
  background: #eef2fa;
}
.lab-ctl {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.lab-ctl-label {
  font-family: monospace;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #8b97ae;
}
.lab-seg {
  display: inline-flex;
  background: #f3f6fc;
  border: 1px solid #c4cee0;
  border-radius: 8px;
  padding: 3px;
  gap: 2px;
}
.lab-seg button {
  font-family: monospace;
  font-size: 12.5px;
  color: #47536b;
  background: transparent;
  border: 0;
  border-radius: 6px;
  padding: 5px 11px;
  cursor: pointer;
}
.lab-seg button[aria-pressed='true'] {
  background: #2563eb;
  color: #fff;
  font-weight: 600;
}
.lab-seg button:hover:not([aria-pressed='true']) {
  color: #101a2b;
}
.lab-run {
  margin-left: auto;
  display: flex;
  gap: 8px;
}
.lab-btn {
  font-family: Helvetica, Arial, sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  border-radius: 8px;
  padding: 8px 15px;
  border: 1px solid transparent;
  white-space: nowrap;
}
.lab-btn.primary {
  background: #2563eb;
  color: #fff;
}
.lab-btn.ghost {
  background: transparent;
  color: #101a2b;
  border-color: #c4cee0;
}
.lab-btn:disabled {
  opacity: 0.5;
  cursor: progress;
}
/* metric readout */
.lab-readout {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-bottom: 1px solid #dce3f0;
}
.lab-metric {
  padding: 12px 14px;
  border-right: 1px solid #dce3f0;
}
.lab-metric:last-child {
  border-right: 0;
}
.lab-metric .k {
  font-family: monospace;
  font-size: 10px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: #8b97ae;
}
.lab-metric .v {
  font-family: monospace;
  font-size: 22px;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  margin-top: 4px;
}
.lab-metric .v small {
  font-size: 12px;
  color: #8b97ae;
  font-weight: 500;
  margin-left: 2px;
}
.lab-metric .v.time {
  color: #2563eb;
}
/* chart stage */
.lab-stage {
  padding: 6px 10px 12px;
  position: relative;
}
.lab-hint {
  font-family: monospace;
  font-size: 11px;
  color: #8b97ae;
  padding: 4px 6px 2px;
}
#chart {
  min-height: 340px;
}
.lab-busy {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.72);
  z-index: 5;
  font-family: monospace;
  font-size: 13px;
  color: #47536b;
}
.lab-busy.on {
  display: flex;
}
/* matrix */
.lab-panel {
  margin-top: 14px;
  background: #fff;
  border: 1px solid #dce3f0;
  border-radius: 12px;
  padding: 16px 18px;
}
.lab-panel h2 {
  font-family: monospace;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #8b97ae;
  font-weight: 600;
  margin: 0 0 12px;
}
.lab-empty {
  color: #8b97ae;
  font-family: monospace;
  font-size: 12.5px;
  margin: 0;
}
.lab-lane {
  display: grid;
  grid-template-columns: 172px 1fr auto;
  gap: 10px;
  align-items: center;
  margin-bottom: 9px;
}
.lab-who {
  font-family: monospace;
  font-size: 11.5px;
  display: flex;
  align-items: center;
  gap: 6px;
  color: #47536b;
}
.lab-who .dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex: none;
}
.lab-meter {
  height: 20px;
  background: #eef2fa;
  border-radius: 5px;
  overflow: hidden;
}
.lab-meter > span {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 5px;
  transition: width 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.lab-num {
  font-family: monospace;
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  min-width: 130px;
  text-align: right;
}
.lab-num em {
  font-style: normal;
  color: #8b97ae;
  font-weight: 500;
}
.lab-verdict {
  font-family: monospace;
  font-size: 12.5px;
  line-height: 1.6;
  color: #47536b;
  margin: 12px 0 0;
}
.lab-verdict b {
  color: #047857;
}
/* side by side */
.lab-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.lab-pair figure {
  margin: 0;
}
/* Deliberately not colour-coded: the matrix above uses amber and green for
     slow and fast, and this panel is about fidelity, not speed. */
.lab-pair figcaption {
  font-family: monospace;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 6px;
  color: #47536b;
}
.lab-pair .count {
  font-family: monospace;
  font-size: 11px;
  color: #8b97ae;
  margin: 4px 0 0;
}
.lab-caption {
  font-size: 12.5px;
  line-height: 1.6;
  color: #47536b;
  margin: 12px 0 0;
}
/* notes */
.lab-notes {
  margin-top: 14px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.lab-note {
  background: #fff;
  border: 1px solid #dce3f0;
  border-radius: 10px;
  padding: 14px;
}
.lab-note h3 {
  margin: 0 0 6px;
  font-size: 13.5px;
}
.lab-note h3 .n {
  font-family: monospace;
  color: #2563eb;
  font-size: 11px;
  margin-right: 7px;
}
.lab-note p {
  margin: 0;
  font-size: 12.5px;
  color: #47536b;
  line-height: 1.5;
}
@media (max-width: 620px) {
  .lab-readout {
    grid-template-columns: repeat(2, 1fr);
  }
  .lab-metric:nth-child(2n) {
    border-right: 0;
  }
  .lab-metric:nth-child(-n + 2) {
    border-bottom: 1px solid #dce3f0;
  }
  .lab-notes,
  .lab-pair {
    grid-template-columns: 1fr;
  }
  .lab-lane {
    grid-template-columns: 130px 1fr;
  }
  .lab-num {
    grid-column: 2;
    text-align: left;
  }
  .lab-run {
    margin-left: 0;
    width: 100%;
  }
  .lab-run .lab-btn {
    flex: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .lab-meter > span {
    transition: none;
  }
}
